{"CommandLine":"python -c "
import requests

endpoints = [
    'http://127.0.0.1:8080/api/accounting/summary',
    'http://127.0.0.1:8080/api/v1/assets/unreal/search?keyword=Chair&limit=2',
    'http://127.0.0.1:8080/api/trading/ledger?limit=3',
    'http://127.0.0.1:8080/api/operations/admin-submissions',
    'http://127.0.0.1:8080/api/operations/continuous-autosaves'
]

for ep in endpoints:
    try:
        r = requests.get(ep, timeout=5)
        print(f'{ep} -> HTTP {r.status_code} ({len(r.text)} bytes)')
        if r.status_code != 200:
            print(f'   Error: {r.text[:200]}')
        else:
            sample = r.text[:120].replace('\n', ' ')
            print(f'   Sample: {sample}...')
    except Exception as e:
        print(f'{ep} -> EXCEPTION: {e}')
